function precomputeDistinct(A){
  const n=A.length;
  const D=Array.from({length:n}, ()=>Array(n).fill(0));
  for(let l=0;l<n;l++){
    const seen=new Set();
    for(let r=l;r<n;r++){
      seen.add(A[r]);
      D[l][r]=seen.size;
    }
  }
  return D;
}
```

